import Image from 'next/image';
import {getTranslations} from 'next-intl/server';
import logoHorizontal from '@/assets/images/brand/logo-horizontal.png';
import logoStacked from '@/assets/images/brand/logo-stacked.png';
import {Link} from '@/i18n/navigation';
import {cn} from '@/lib/utils';

type Props = {
  className?: string;
  /** `horizontal` fits the header bar; `stacked` is the logo's original layout (footer). */
  variant?: 'horizontal' | 'stacked';
};

// Both files are the on-dark version of the logo, generated by `scripts/generate-brand-assets.mjs`.
export async function Brand({className, variant = 'horizontal'}: Props) {
  const t = await getTranslations('Doctor');
  const stacked = variant === 'stacked';

  return (
    <Link href="/" className={cn('inline-flex shrink-0 transition-opacity hover:opacity-85', className)}>
      <Image
        src={stacked ? logoStacked : logoHorizontal}
        alt={t('name')}
        loading={stacked ? 'lazy' : 'eager'}
        className={stacked ? 'h-40 w-auto' : 'h-10 w-auto sm:h-12'}
      />
    </Link>
  );
}
